Method.Implementation:
	#dim source As EnsLib.EDI.X12.Document
	if ( fileStream.Size < 100)
	{
		return "Stream size is not valid"
	}

 	#dim lst  As %ListOfObjects = ##class(%ListOfObjects).%New()
	#dim lst2  As %ListOfObjects = ##class(%ListOfObjects).%New()

	 #dim x12Doc As EnsLib.EDI.X12.Document = ##class(EnsLib.EDI.X12.Document).ImportFromLibraryStream(fileStream, .tSC)

	 Do ..SplitX12AtGroup(x12Doc, lst)

	 for IND=1:1:lst.Size
	 {
	 	WRITE !, "  -" _ IND _". Split: GS/GE: " 

	 	#dim gsDoc As EnsLib.EDI.X12.Document = ##class(EnsLib.EDI.X12.Document).ImportFromLibraryStream(lst.GetAt(IND),.x12Stat)

	    Do ..SplitX12AtTransaction(gsDoc, lst2)
	 }

	 for IND2=1:1:lst2.Size
	 {
	    #dim stDoc As EnsLib.EDI.X12.Document = ##class(EnsLib.EDI.X12.Document).ImportFromLibraryStream(lst2.GetAt(IND2),.x12Stat)
	    	WRITE !, "   -- " _IND2 _". Split ST/SE: " 
	    	#dim x12Stream As %Stream.GlobalCharacter = ##class(%Stream.GlobalCharacter).%New()
	    	Do ..SplitX12AtClm(stDoc, x12Stream)
	    	Do x12List.Insert(x12Stream)
	 }

	set MultiSplit = 0
	if ( ($ISOBJECT(x12Doc)) && (x12Doc.%Extends("EnsLib.EDI.X12.Document")) )
	 {
		 $$$TRACE( "SplitX12: Process X12: " _ x12Doc.FullSize  _", Separators: " _ x12Doc.Separators)
		 set segSep = $EXTRACT(x12Doc.Separators, 4)
		 set eleSep = $EXTRACT(x12Doc.Separators, 1, 1)
	 }
	 else
	 {
		 WRITE !, "SplitX12: Not a valid X12 Document"
		 QUIT
	 }
	 if (x12Doc.DocType = "")
	 {
 		set x12Doc.DocType = "HIPAA_5010:Interchange:Group"
	 }
	  Set tSC =x12Doc.BuildMap()
	  if ($$$ISERR( tSC ))
	  {
		  $$$TRACE("SplitX12: Invalid DocType")
		  QUIT
	  }
	  set GSCounter = x12Doc.ChildCount 
	  $$$TRACE( " ISA Child count:" _ GSCounter _", Seg #" _ x12Doc.SegCount)

 	if (GSCounter > 1)
 	{

	 	set MultiSplit = 1

	 	//ISA // IEA	  
		set isaPath = x12Doc.GetSegmentPath(1, .stat)	  	
	  	set isaVal = x12Doc.GetValueAt(isaPath,, .stat)

	  	set ieaPath = x12Doc.GetSegmentPath(3, .stat)	
		Do x12Doc.SetValueAt(1, ieaPath_":1")  	
		set ieaVal = x12Doc.GetValueAt(ieaPath,, .stat)

		#dim individualGroup As EnsLib.EDI.X12.Document = $$$NULLOREF	
	 	for gsInt=1:1:GSCounter
	    {
	 		#dim x12Stream As %Stream.GlobalCharacter = ##class(%Stream.GlobalCharacter).%New()

	 		Do x12Stream.Write(isaVal _ segSep) 
	        set individualGroup = x12Doc.NextChild(individualGroup) // x12Doc.getNthChild(gsInt,2)

			if (individualGroup.DocType = "")
			{
		 		set individualGroup.DocType = "HIPAA_5010:Group"
			}

			// GS	    	  
			set segPath = individualGroup.GetSegmentPath(1, .stat1)	  	
		  	set segVal = individualGroup.GetValueAt(segPath,, .stat2)
		  	Do x12Stream.Write( segVal _ segSep)

		  	#dim STRecord As EnsLib.EDI.X12.Document = $$$NULLOREF		  	
		  	FOR stInd=1:1:individualGroup.ChildCount		  
		 	{			  		  
				  set STRecord=individualGroup.NextChild(STRecord) 
				  Do x12Stream.Write(STRecord.OutputToString())
		  	}

		    // GE
			set segPath = individualGroup.GetSegmentPath(3, .stat1)	  					
			set segVal = individualGroup.GetValueAt(segPath,, .stat2)

			Do x12Stream.Write( segVal _ segSep)

			// IEA

			WRITE !, "GS-GE loop complete: " _ segVal _ segSep
		  	Do x12Stream.Write( ieaVal _ segSep)

		  	Do x12Stream.Rewind()	
		  	WRITE !, "Insert to list"
		  	Do list.Insert(x12Stream)	  	

	    }
 	}

    if (MultiSplit = 0)
    {

	       WRITE !, "X12 has one GS-GE, send back original X12"
	       #dim x12Stream As %Stream.GlobalCharacter = ##class(%Stream.GlobalCharacter).%New()
	       Do x12Doc.OutputToLibraryStream(x12Stream) // Copy inbound X12
	       Do x12Stream.Rewind()
	       Do list.Insert(x12Stream)	
      }

      WRITE !, "Return GS-GE list " _ list.Size

	set MultiSplit = 0
	if ( ($ISOBJECT(x12Doc)) && (x12Doc.%Extends("EnsLib.EDI.X12.Document")) )
	 {
		 $$$TRACE( "SplitX12: Process X12: " _ x12Doc.FullSize  _", Separators: " _ x12Doc.Separators)
		 set segSep = $EXTRACT(x12Doc.Separators, 4)
		 set eleSep = $EXTRACT(x12Doc.Separators, 1, 1)
	 }
	 else
	 {
		 WRITE !, "SplitX12: Not a valid X12 Document"
		 QUIT
	 }
	 if (x12Doc.DocType = "")
	 {
 		set x12Doc.DocType = "HIPAA_5010:Interchange:Group"
	 }
	  Set tSC =x12Doc.BuildMap()
	  if ($$$ISERR( tSC ))
	  {
		  $$$TRACE("SplitX12: Invalid DocType")
		  QUIT
	  }

	 	//ISA / IEA	  
		set isaPath = x12Doc.GetSegmentPath(1, .stat)	  	
	  	set isaVal = x12Doc.GetValueAt(isaPath,, .stat)

	  	set ieaPath = x12Doc.GetSegmentPath(3, .stat)	
		Do x12Doc.SetValueAt(1, ieaPath_":1")  	
		set ieaVal = x12Doc.GetValueAt(ieaPath,, .stat)

		#dim individualGroup As EnsLib.EDI.X12.Document = $$$NULLOREF	

	        set individualGroup = x12Doc.NextChild(individualGroup) // x12Doc.getNthChild(gsInt,2)

			if (individualGroup.DocType = "")
			{
		 		set individualGroup.DocType = "HIPAA_5010:Group"
			}
			// GS	    	  
			set gsPath = individualGroup.GetSegmentPath(1, .stat1)	  	
		  	set gsVal = individualGroup.GetValueAt(gsPath,, .stat2) 
		  	// GE
			set gePath = individualGroup.GetSegmentPath(3, .stat1)
			Do individualGroup.SetValueAt(1, gePath_":1")	  					
			set geVal = individualGroup.GetValueAt(gePath,, .stat2)

			if (individualGroup.ChildCount > 1)
		  	{
	 			set MultiSplit = 1
	 			#dim STRecord As EnsLib.EDI.X12.Document = $$$NULLOREF
	 			FOR stInd=1:1:individualGroup.ChildCount		  
			 	{	  	
			 		#dim x12Stream As %Stream.GlobalCharacter = ##class(%Stream.GlobalCharacter).%New()

			 		Do x12Stream.Write(isaVal _ segSep)			 		

				  	Do x12Stream.Write(gsVal _ segSep)

					set STRecord=individualGroup.NextChild(STRecord) 
					Do x12Stream.Write(STRecord.OutputToString())

					// WRITE !, "ST-SE loop complete: "

					Do x12Stream.Write( geVal _ segSep)

					// IEA

				  	Do x12Stream.Write( ieaVal _ segSep)

				  	Do x12Stream.Rewind()	
				  	WRITE !, "Insert to X12 list: " _ list.Count()
				  	Do list.Insert(x12Stream)
		  		}
		  }	  	


    if (MultiSplit = 0)
    {

	       WRITE !, "X12 has one ST_SE, send back original X12"
	       #dim x12Stream As %Stream.GlobalCharacter = ##class(%Stream.GlobalCharacter).%New()
	       Do x12Doc.OutputToLibraryStream(x12Stream) // Copy inbound X12
	       Do x12Stream.Rewind()
	       Do list.Insert(x12Stream)	
      }

      WRITE !, "Return ST_SE list " _ list.Size

	set MultiSplit = 0, segSep = "", eleSep = "" 
	if ( ($ISOBJECT(x12Doc)) && (x12Doc.%Extends("EnsLib.EDI.X12.Document")) )
	 {
		 $$$TRACE( "SplitX12AtClm: Process X12: " _ x12Doc.FullSize  _", Separators: " _ x12Doc.Separators)
		 set segSep = $EXTRACT(x12Doc.Separators, 4)
		 if (segSep = "")
		 {
			 set segSep = "~"
		 }
		 set eleSep = $EXTRACT(x12Doc.Separators, 1, 1)
	 }
	 else
	 {
		 WRITE !, "SplitX12AtClm: Not a valid X12 Document"
		 QUIT
	 }
	 if (x12Doc.DocType = "")
	 {
 		set x12Doc.DocType = "HIPAA_5010:Interchange:Group"
	 }
	  Set tSC =x12Doc.BuildMap()
	  if ($$$ISERR( tSC ))
	  {
		  $$$TRACE("SplitX12AtClm: Invalid DocType")
		  QUIT
	  }


    //ISA	  
	set segPath = x12Doc.GetSegmentPath(1, .stat)	  	
  	set segVal = x12Doc.GetValueAt(segPath,, .stat)
  	Do x12Stream.Write(segVal _ segSep)



 	#dim individualGroup As EnsLib.EDI.X12.Document = $$$NULLOREF
 	WRITE !, "^segments"
 	kill ^segments
 	set splitX12 = 1, stCtrl = 0, origSts = 0, segPath = "", segVal = ""


	set individualGroup = x12Doc.NextChild(individualGroup) // x12Doc.getNthChild(gsInt,2)


	if (individualGroup.DocType = "")
	{
	set individualGroup.DocType = "HIPAA_5010:Group"
	}
	set origSts = individualGroup.ChildCount
	WRITE !, individualGroup.DocType _ " # of STs: " _ origSts _", Seg # " _ individualGroup.SegCount



	// GS	    	  
	set segPath = individualGroup.GetSegmentPath(1, .stat1)	  	
	set segVal = individualGroup.GetValueAt(segPath,, .stat2)
	Do x12Stream.Write( segVal _ segSep)

	#dim STRecord As EnsLib.EDI.X12.Document = $$$NULLOREF
	set segNum = 0, ctrlNum = 0

	  set STRecord=individualGroup.NextChild(STRecord)  
	  set transType = ##class(IHC.ITF.ITFCOMMON.X12.StoreEdiX12Data).GetTransType(STRecord)
	  if (STRecord.DocType = "")
	  {	
	  	set STRecord.DocType = "HIPAA_5010:" _ transType
	  	$$$TRACE( "DocType: " _ STRecord.DocType)
	  }

	  // ST control number
	  set segPath = STRecord.GetSegmentPath(1, .stat)	  	
	  set stCtrl = STRecord.GetValueAt(segPath_":2",, .stat)

	  //  WRITE !, " " _ segPath _"= " _ stCtrl

	  WRITE !, " " _ transType _ ". ST segments: " _ STRecord.SegCountGet()
	  set idHL = 0,  idParentHL = -1
	  set segClmFound = 0, segInd = 1, split2000 = 0, clmSegVal = ""
	  FOR ind=1:1:STRecord.SegCountGet()
	  {		

			set segPath = STRecord.GetSegmentPath(ind, .stat)	  	
		  	set segVal = STRecord.GetValueAt(segPath,, .stat)
		  	if ( (segPath = "") || (segVal = ""))
		  	{
			  	WRITE !, ind _ " is empty. " _ stat
			  	QUIT
		  	}
		  	// WRITE !, segPath _"= " _ segVal			  	
		  	set res = $MATCH(segPath, "loop2000A\([0-9]+\)\.HL.*")
		  	if ( res )
		  	{
			  	//Do STRecord.SetValueAt(1, segPath_":1")
				set segVal = STRecord.GetValueAt(segPath,, .stat)

			  	if (segClmFound)
			  	{
				  	$$$TRACE( "-- SPLIT @ A: " _ segInd _ ", " _ aInd _", " _ clmSegVal)
				  	set segNum = ..TraverseGlobal(idHL, segSep, eleSep,  .ctrlNum, split2000, x12Stream)

				  	Do x12Stream.Write( "SE" _ eleSep _ segNum _ eleSep _ $tr($j(ctrlNum,4)," ","0") _ segSep)
				  	set segInd = 1
				  	Do $INCREMENT(splitX12)
				  	set segClmFound = 0, split2000 = 1
				  	kill ^segments(idHL)

			  	}
			  	else
			  	{
				  	set aInd = segInd
			  	}

			  	// WRITE !, "-A." _ segPath _"= " _ segVal
			  	set idHL = STRecord.GetValueAt(segPath_":1",, .stat)
			  	set idParentHL = 0, segInd = 1


		  	}

		  	set res = $MATCH(segPath, "loop2000A.*loop2000B\([0-9]+\)\.HL.*")
		  	if ( res )
		  	{
			  	if (segClmFound)
			  	{
				  	$$$TRACE( "   -- SPLIT @ B" _", Indexes: " _ idHL _", " _ idParentHL_", " _ segInd  _ ", " _ bInd _", " _ clmSegVal)
				   	set segNum = ..TraverseGlobal(idHL, segSep, eleSep,  .ctrlNum, split2000, x12Stream)
				  	Do x12Stream.Write( "SE" _ eleSep _ segNum _ eleSep _ $tr($j(ctrlNum,4)," ","0") _ segSep)

				  	set segInd = 1
				  	Do $INCREMENT(splitX12)
				  	set segClmFound = 0, split2000 = 1
				  	kill ^segments(idHL, idParentHL)

			  	}
			  	else
			  	{
				  	set bInd = segInd
			  	}

			  	// WRITE !, " -B. " _ segPath _"= " _ segVal 
			  	set idHL = STRecord.GetValueAt(segPath_":1",, .stat)
			  	set idParentHL = STRecord.GetValueAt(segPath_":2",, .stat)
			  	set segInd = 1
		  	}
		  	set res = $MATCH(segPath, "loop2000A.*loop2000B.*loop2000C\([0-9]+\)\.HL.*")
		  	if ( res )
		  	{
			  	if (segClmFound)
			  	{
				  	$$$TRACE( "   -- SPLIT @ C " _", Indexes: " _ idHL _", " _ idParentHL_", " _ segInd _", " _ cInd _", " _ clmSegVal)
				  	set segNum = ..TraverseGlobal(idHL, segSep, eleSep,  .ctrlNum, split2000, x12Stream)
				  	Do x12Stream.Write( "SE" _ eleSep _ segNum _ eleSep _ $tr($j(ctrlNum,4)," ","0") _ segSep)

				  	set segInd = 1
				  	Do $INCREMENT(splitX12)
				  	set segClmFound = 0, split2000 = 1
				  	kill ^segments(idHL, idParentHL)


			  	}
			  	else
			  	{
				  	set cInd = segInd
			  	}

			  	// WRITE !, " -C. " _ segPath _"= " _ segVal 
			  	set idHL = STRecord.GetValueAt(segPath_":1",, .stat)
			  	set idParentHL = STRecord.GetValueAt(segPath_":2",, .stat)
			  	set segInd = 1
		  	}
		  	if ( $FIND(segVal, "CLM") = 4  )
		  	{

			  	if (segClmFound)
			  	{
				  	$$$TRACE( "   -- SPLIT @ CLM, Indexes: " _ idHL _ ", " _ idParentHL_", " _ segInd_", " _ clmInd _", " _ clmSegVal)

				  	set segNum = ..TraverseGlobal(idHL, segSep, eleSep,  .ctrlNum, split2000, x12Stream)
				  	Do x12Stream.Write( "SE" _ eleSep _ segNum _ eleSep _ $tr($j(ctrlNum,4)," ","0") _ segSep)
				  	// WRITE !, "   -- Kill @ CLM " _idHL _", " _ idParentHL _", from " _  clmInd _ " to " _ (segInd-1)

				  	FOR clmNum=clmInd:1:segInd-1
				  	{
				  		kill ^segments(idHL, idParentHL, clmNum)

				  	}

				  	set segInd = clmInd
				  	Do $INCREMENT(splitX12)
				  	set segClmFound = 0, split2000 = 1

			  	}

				set clmInd = segInd, clmSegVal = segVal

			  	// WRITE !, "    --- " _ ind _". " _ segVal _" <- " _ segPath _ ", $STORAGE=",$S
			  	set segClmFound = 1

		  	}
		  	if ( $FIND(segVal, "SE") = 3  )
		  	{
			  	$$$TRACE( "   -- SPLIT @ SE --" _ segPath _"= " _ segVal _", Indexes: " _ idHL _", " _ idParentHL_", " _ segInd_", " _ clmSegVal)
			  	if (segClmFound)
			  	{
				  	set segNum = ..TraverseGlobal(idHL, segSep, eleSep, .ctrlNum, split2000, x12Stream)
				  	$$$TRACE(" -> SE" _ eleSep _ segNum _ eleSep _ ctrlNum _ segSep)
				  	Do x12Stream.Write( "SE" _ eleSep _ segNum _ eleSep _ $tr($j(ctrlNum,4)," ","0") _ segSep)
				  	set split2000 = 0

				  	DO $INCREMENT(splitX12)
				  	kill ^segments(idHL)

			  	}
		  	}
		  	else // Copy all segments except SE
		  	{
		  	  set ^segments(idHL, idParentHL, segInd) = segVal
			  // WRITE !, idHL _", " _ idParentHL_", " _  segInd_"= " _  segVal
		  	}

			Do $INCREMENT(segInd)
			if ((splitX12  - 1) > origSts)
		    {		    
			  	set MultiSplit = 1
		    }
	  }
	  if (MultiSplit = 1)
      {

		    // WRITE !, "Loop ST-SE exit: " _ segInd _", " _ segPath _" =   " _ segVal
		    // GE
			set segPath = individualGroup.GetSegmentPath(3, .stat1)	  		
			Do individualGroup.SetValueAt("" _ (splitX12-1), segPath _":1") // Update GE:1 
			set segVal = individualGroup.GetValueAt(segPath,, .stat2)
			Do x12Stream.Write( segVal _ segSep)

		    set segPath = x12Doc.GetSegmentPath(3, .stat)	  	
		  	set segVal = x12Doc.GetValueAt(segPath,, .stat)

			// IEA
			// WRITE !, "   SplitX12AtClm GS-GE loop complete: " _ segVal _ segSep
		  	Do x12Stream.Write( segVal _ segSep)

		  	$$$TRACE( "   SplitX12AtClm New Split X12 Size: " _ x12Stream.Size)
		  	Do x12Stream.Rewind()
		  	$$$TRACE( "   SplitX12AtClm # of splits: " _ (splitX12  - 1) _", Inbound ST-SEs: " _ origSts _ ", X12 Size: " _ x12Stream.Size)
		  	// $$$TRACE( "# of splits: " _ (splitX12  - 1) _", Inbound ST-SEs: " _ origSts )

		  	// WRITE !, "X12: " _ x12Stream.Read()
		  	Do x12Stream.Rewind()

		  	#dim x12Doc2 As EnsLib.EDI.X12.Document = ##class(EnsLib.EDI.X12.Document).ImportFromLibraryStream(x12Stream,.x12Stat)
		   #dim x12Stream2 As %Stream.GlobalCharacter = ##class(%Stream.GlobalCharacter).%New()
		   Do ..ResetIDs(x12Doc2, x12Stream2)
		   Do x12Stream.CopyFrom(x12Stream2)
	  }
	  else
	  { 
	       $$$TRACE( "   SplitX12AtClm X12 has one Subscriber information in each ST-SE, send back original X12")
	       Do x12Stream.Clear()
	       Do x12Doc.OutputToLibraryStream(x12Stream) // Copy inbound X12
	       Do x12Stream.Rewind()
		   $$$TRACE( "   SplitX12AtClm Unchanged X12 Size: " _ x12Stream.Size)
      }
      $$$TRACE( "   SplitX12AtClm: Return stream: " _ x12Stream.Size)

	set MultiSplit = 0
	if ( ($ISOBJECT(x12Doc)) && (x12Doc.%Extends("EnsLib.EDI.X12.Document")) )
	 {
		 $$$TRACE( "SplitX12: Process X12: " _ x12Doc.FullSize  _", Separators: " _ x12Doc.Separators)
		 set segSep = $EXTRACT(x12Doc.Separators, 4)
		 set eleSep = $EXTRACT(x12Doc.Separators, 1, 1)
	 }
	 else
	 {
		 $$$LOGERROR( "SplitX12: Not a valid X12 Document")
		 QUIT
	 }
	 if (x12Doc.DocType = "")
	 {
 		set x12Doc.DocType = "HIPAA_5010:Interchange:Group"
	 }
	  Set tSC =x12Doc.BuildMap()
	  if ($$$ISERR( tSC ))
	  {
		  $$$TRACE("SplitX12: Invalid DocType")
		  QUIT
	  }
	  set GSCounter = x12Doc.ChildCount 
	  $$$TRACE( " ISA Child count:" _ GSCounter _", Seg #" _ x12Doc.SegCount)


    //ISA	  
	set segPath = x12Doc.GetSegmentPath(1, .stat)	  	
  	set segVal = x12Doc.GetValueAt(segPath,, .stat)
  	Do x12Stream.Write(segVal _ segSep)



 	#dim individualGroup As EnsLib.EDI.X12.Document = $$$NULLOREF
 	kill ^segments
 	set splitX12 = 1, stCtrl = 0, origSts = 0, segPath = "", segVal = ""


	for gsInt=1:1:GSCounter
    { 

        set individualGroup = x12Doc.NextChild(individualGroup) // x12Doc.getNthChild(gsInt,2)


		if (individualGroup.DocType = "")
		 {
	 		set individualGroup.DocType = "HIPAA_5010:Group"
		 }
		 set origSts = individualGroup.ChildCount
		// WRITE !, individualGroup.DocType _ " # of STs: " _ origSts _", Seg # " _ individualGroup.SegCount



		// GS	    	  
		set segPath = individualGroup.GetSegmentPath(1, .stat1)	  	
	  	set segVal = individualGroup.GetValueAt(segPath,, .stat2)
	  	Do x12Stream.Write( segVal _ segSep)

		  #dim STRecord As EnsLib.EDI.X12.Document = $$$NULLOREF
		  set segNum = 0, ctrlNum = 0
		  FOR stInd=1:1:individualGroup.ChildCount

		  {
			  // WRITE !, "Process ST: " _ stInd		  
			  set STRecord=individualGroup.NextChild(STRecord)  
			  set transType = ##class(IHC.ITF.ITFCOMMON.X12.StoreEdiX12Data).GetTransType(STRecord)
			  if (STRecord.DocType = "")
			  {	
			  	set STRecord.DocType = "HIPAA_5010:" _ transType
			  	$$$TRACE( "DocType: " _ STRecord.DocType)
			  }

			  // ST control number
			  set segPath = STRecord.GetSegmentPath(1, .stat)	  	
			  set stCtrl = STRecord.GetValueAt(segPath_":2",, .stat)

	  		  //  WRITE !, " " _ segPath _"= " _ stCtrl

	  		  $$$TRACE( " " _ transType _ ". ST segments: " _ STRecord.SegCountGet())
	  		  set idHL = 0,  idParentHL = -1
	  		  set segClmFound = 0, segInd = 1, split2000 = 0
			  FOR ind=1:1:STRecord.SegCountGet()
			  {		

				set segPath = STRecord.GetSegmentPath(ind, .stat)	  	
			  	set segVal = STRecord.GetValueAt(segPath,, .stat)
			  	if ( (segPath = "") || (segVal = ""))
			  	{
				  	$$$TRACE( ind _ " is empty. " _ stat)
				  	QUIT
			  	}
			  	// WRITE !, segPath _"= " _ segVal			  	
			  	set res = $MATCH(segPath, "loop2000A\([0-9]+\)\.HL.*")
			  	if ( res )
			  	{
				  	//Do STRecord.SetValueAt(1, segPath_":1")
					set segVal = STRecord.GetValueAt(segPath,, .stat)

				  	if (segClmFound)
				  	{
					  	// WRITE !, "-- SPLIT @ A"
					  	set segNum = ..TraverseGlobal(idHL, segSep, eleSep,  .ctrlNum, split2000, x12Stream)

					  	Do x12Stream.Write( "SE" _ eleSep _ segNum _ eleSep _ $tr($j(ctrlNum,4)," ","0") _ segSep)
					  	set segInd = 1
					  	Do $INCREMENT(splitX12)
					  	set segClmFound = 0, split2000 = 1
					  	kill ^segments(idHL)

				  	}

				  	// WRITE !, "-A." _ segPath _"= " _ segVal
				  	set idHL = STRecord.GetValueAt(segPath_":1",, .stat)
				  	set idParentHL = 0, segInd = 1


			  	}

			  	set res = $MATCH(segPath, "loop2000A.*loop2000B\([0-9]+\)\.HL.*")
			  	if ( res )
			  	{
				  	if (segClmFound)
				  	{
					  	// WRITE !, "-- SPLIT @ B" 
					   	set segNum = ..TraverseGlobal(idHL, segSep, eleSep,  .ctrlNum, split2000, x12Stream)
					  	Do x12Stream.Write( "SE" _ eleSep _ segNum _ eleSep _ $tr($j(ctrlNum,4)," ","0") _ segSep)

					  	set segInd = 1
					  	Do $INCREMENT(splitX12)
					  	set segClmFound = 0, split2000 = 1
					  	kill ^segments(idHL, idParentHL)

				  	}

				  	// WRITE !, " -B. " _ segPath _"= " _ segVal 
				  	set idHL = STRecord.GetValueAt(segPath_":1",, .stat)
				  	set idParentHL = STRecord.GetValueAt(segPath_":2",, .stat)

				  	set segInd = 1
			  	}
			  	set res = $MATCH(segPath, "loop2000A.*loop2000B.*loop2000C\([0-9]+\)\.HL.*")
			  	if ( res )
			  	{
				  	if (segClmFound)
				  	{
					  	// WRITE !, "-- SPLIT @ C " 
					  	set segNum = ..TraverseGlobal(idHL, segSep, eleSep,  .ctrlNum, split2000, x12Stream)
					  	Do x12Stream.Write( "SE" _ eleSep _ segNum _ eleSep _ $tr($j(ctrlNum,4)," ","0") _ segSep)

					  	set segInd = 1
					  	Do $INCREMENT(splitX12)
					  	set segClmFound = 0, split2000 = 1
					  	kill ^segments(idHL, idParentHL)


				  	}

				  	// WRITE !, " -C. " _ segPath _"= " _ segVal 
				  	set idHL = STRecord.GetValueAt(segPath_":1",, .stat)
				  	set idParentHL = STRecord.GetValueAt(segPath_":2",, .stat)



				  	set segInd = 1
			  	}
			  	if ( $FIND(segVal, "CLM") = 4  )
			  	{
				  	if (segClmFound)
				  	{
					  	// WRITE !, "-- SPLIT @ CLM "

					  	set segNum = ..TraverseGlobal(idHL, segSep, eleSep,  .ctrlNum, split2000, x12Stream)
					  	Do x12Stream.Write( "SE" _ eleSep _ segNum _ eleSep _ $tr($j(ctrlNum,4)," ","0") _ segSep)

					  	set segInd = 1
					  	Do $INCREMENT(splitX12)
					  	set segClmFound = 0, split2000 = 1

				  	}
				  	// WRITE !, "    --- " _ ind _". " _ segVal _" <- " _ segPath _ ", $STORAGE=",$S
				  	set segClmFound = 1

			  	}
			  	if ( $FIND(segVal, "SE") = 3  )
			  	{
				  	$$$TRACE( "-- SPLIT @ SE --" _ segPath _"= " _ segVal _", Indexes: " _ idHL _", " _ idParentHL_", " _ segInd)
				  	if (segClmFound)
				  	{
					  	set segNum = ..TraverseGlobal(idHL, segSep, eleSep, .ctrlNum, split2000, x12Stream)
					  	$$$TRACE(" -> SE" _ eleSep _ segNum _ eleSep _ ctrlNum _ segSep)
					  	Do x12Stream.Write( "SE" _ eleSep _ segNum _ eleSep _ $tr($j(ctrlNum,4)," ","0") _ segSep)
					  	set split2000 = 0

					  	DO $INCREMENT(splitX12)
					  	kill ^segments(idHL)

				  	}
			  	}
			  	else
			  	{
			  	  set ^segments(idHL, idParentHL, segInd) = segVal
				  //WRITE !, idHL _", " _ idParentHL_", " _  segInd_"= " _  segVal
			  	}

				  Do $INCREMENT(segInd)


			  }
		  }

	    WRITE !, "Loop ST-SE exit: " _ segInd _", " _ segPath _" =   " _ segVal
	    // GE
		set segPath = individualGroup.GetSegmentPath(3, .stat1)	  		
		Do individualGroup.SetValueAt("" _ (splitX12-1), segPath _":1") // Update GE:1 
		set segVal = individualGroup.GetValueAt(segPath,, .stat2)
		Do x12Stream.Write( segVal _ segSep)

	    if ((splitX12  - 1) > origSts)
