	    Do ..SplitX12AtTransaction(gsDoc, lst2)
	 }

	 for IND2=1:1:lst2.Size
	 {
	    #dim stDoc As EnsLib.EDI.X12.Document = ##class(EnsLib.EDI.X12.Document).ImportFromLibraryStream(lst2.GetAt(IND2),.x12Stat)
	    	WRITE !, "   -- " _IND2 _". Call  SplitX12At2000C for " _ stDoc
	    	//Do ..SplitX12At2000C(stDoc,x12List)
	    	Do ..SplitX12AtClaim(stDoc,x12List)

	 }

	set MultiSplit = 0

	if ( ($ISOBJECT(x12Doc)) && (x12Doc.%Extends("EnsLib.EDI.X12.Document")) )
	 {
		 $$$TRACE( "SplitX12: Process X12: " _ x12Doc.FullSize  _", Separators: " _ x12Doc.Separators)
		 set segSep = $EXTRACT(x12Doc.Separators, 4)
		 set eleSep = $EXTRACT(x12Doc.Separators, 1, 1)
	 }
	 else
	 {
		 WRITE !, "SplitX12At2000C: Not a valid X12 Document"
		 QUIT
	 }
	 if (x12Doc.DocType = "")
	 {
 		set x12Doc.DocType = "HIPAA_5010:Interchange:Group"
	 }
	  Set tSC =x12Doc.BuildMap()
	  if ($$$ISERR( tSC ))
	  {
		  $$$TRACE("SplitX12At2000C: Invalid DocType")
		  QUIT
	  }

	 	//ISA / IEA	  
		set isaPath = x12Doc.GetSegmentPath(1, .stat)	  	
	  	set isaVal = x12Doc.GetValueAt(isaPath,, .stat)

	  	set ieaPath = x12Doc.GetSegmentPath(3, .stat)	
		Do x12Doc.SetValueAt(1, ieaPath_":1")  	
		set ieaVal = x12Doc.GetValueAt(ieaPath,, .stat)

		#dim individualGroup As EnsLib.EDI.X12.Document = $$$NULLOREF	

	        set individualGroup = x12Doc.NextChild(individualGroup) // x12Doc.getNthChild(gsInt,2)

			if (individualGroup.DocType = "")
			{
		 		set individualGroup.DocType = "HIPAA_5010:Group"
			}
			// GS	    	  
			set gsPath = individualGroup.GetSegmentPath(1, .stat1)	  	
		  	set gsVal = individualGroup.GetValueAt(gsPath,, .stat2) 
		  	// GE
			set gePath = individualGroup.GetSegmentPath(3, .stat1)
			Do individualGroup.SetValueAt(1, gePath_":1")	  					
		set geVal = individualGroup.GetValueAt(gePath,, .stat2)


		#dim STRecord As EnsLib.EDI.X12.Document = $$$NULLOREF

		#dim x12Stream As %Stream.GlobalCharacter = ##class(%Stream.GlobalCharacter).%New()
		set STRecord=individualGroup.getNthChild(1)


		set lastHLval =0, nextHlval = 1
		set prev2000C = 0, segInd = 1, split2000C = 0

		  FOR ind=1:1:STRecord.SegCountGet()
		  {		

				set segPath = STRecord.GetSegmentPath(ind, .stat)	  	
			  	set segVal = STRecord.GetValueAt(segPath,, .stat)
			  	if ( (segPath = "") || (segVal = ""))
			  	{
				  	WRITE !, ind _ " is empty. " _ stat
				  	QUIT
			  	}
			  	// WRITE !, ind _". " _ segPath _"= " _ segVal			  	
			  	set res = $MATCH(segPath, ".*.loop2000C\([0-9]+\)\.HL.*")
			  	if ( res )
			  	{
				  	set nextHlval = 1
					set segVal = STRecord.GetValueAt(segPath,, .stat)
					Do STRecord.SetValueAt( "" _ (lastHLval + nextHlval) ,segPath_":1")
					Do STRecord.SetValueAt( "" _ (lastHLval + nextHlval - 1) ,segPath_":2")
					// WRITE !, "SET loop2000C: " _ (lastHLval + nextHlval) _", " _ segPath _"= " _ STRecord.GetValueAt(segPath_":1",, .stat)
					Do $INCREMENT(nextHlval)

					if (split2000C = 0)
					{
						set split2000C = ind
				  	}
				  	else
				  	{					  						  					  									  	
					  	set x12Stream  = ##class(%Stream.GlobalCharacter).%New()
					  	//ISA	  
				 		Do x12Stream.Write(isaVal _ segSep)			 		
						//GS
					  	Do x12Stream.Write(gsVal _ segSep)

					  	set stLen = 1
					  	FOR loopC=1:1:(split2000C - 1)
					  	{
					  		Do x12Stream.Write( STRecord.GetValueAt(STRecord.GetSegmentPath(loopC, .stat))_ segSep)
					  		Do $INCREMENT(stLen)
				  		}
					  	FOR loopC=prev2000C:1:(ind -1)
