					  		Do $INCREMENT(stLen)
				  		}
				  		Do STRecord.SetValueAt(stLen, STRecord.SegCountGet()_":1")
					  	Do x12Stream.Write(  STRecord.GetValueAt(STRecord.GetSegmentPath(STRecord.SegCountGet(), .stat))_ segSep)

